using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;
using Microsoft.AspNetCore.Mvc;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;
        private readonly NotificationService _notificationService;

        public NotificationsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new NotificationsController(_context);
            _notificationService = new NotificationService();
            // Drain the static queue to isolate tests
            while (_notificationService.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain queue
            while (_notificationService.ReceiveNotification() != null) { }
            _controller.Dispose();
            _context.Dispose();
            _notificationService.Dispose();
        }

        [Fact]
        public void GetNotifications_ReturnsNotifications_WhenAvailable()
        {
            // Arrange - enqueue some notifications
            _notificationService.SendNotification("Student", "1", "John", EntityOperation.CREATE);
            _notificationService.SendNotification("Course", "2", "Math", EntityOperation.UPDATE);

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.NotNull(result);
            var json = result.Value;
            Assert.NotNull(json);
            var successProp = json.GetType().GetProperty("success");
            Assert.NotNull(successProp);
            Assert.True((bool)successProp.GetValue(json));

            var countProp = json.GetType().GetProperty("count");
            Assert.NotNull(countProp);
            var count = (int)countProp.GetValue(json);
            Assert.True(count >= 1);
        }

        [Fact]
        public void GetNotifications_ReturnsEmptyList_WhenNoNotifications()
        {
            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.NotNull(result);
            var json = result.Value;
            var successProp = json.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(json));

            var countProp = json.GetType().GetProperty("count");
            var count = (int)countProp.GetValue(json);
            Assert.Equal(0, count);
        }

        [Fact]
        public void GetNotifications_LimitsToTen()
        {
            // Arrange - add 15 notifications
            for (int i = 0; i < 15; i++)
            {
                _notificationService.SendNotification("Entity", i.ToString(), $"Item{i}", EntityOperation.CREATE);
            }

            // Act
            var result = _controller.GetNotifications();

            // Assert
            var json = result.Value;
