using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;
using Microsoft.EntityFrameworkCore;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests.Utilities
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_SetsCorrectPageIndex()
        {
            // Arrange
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act
            var result = PaginatedList<Student>.Create(query, 1, 2);

            // Assert
            Assert.Equal(1, result.PageIndex);
        }

        [Fact]
        public void Create_CalculatesTotalPagesCorrectly()
        {
            // Arrange - 5 students, page size 2 => ceil(5/2) = 3 pages
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act
            var result = PaginatedList<Student>.Create(query, 1, 2);

            // Assert
            Assert.Equal(3, result.TotalPages);
        }

        [Fact]
        public void Create_ReturnsCorrectPageSize()
        {
            // Arrange
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act
            var result = PaginatedList<Student>.Create(query, 1, 2);

            // Assert
            Assert.Equal(2, result.Count);
        }

        [Fact]
        public void Create_PageTwo_SkipsFirstPageItems()
        {
            // Arrange
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);
            var allSorted = query.ToList();

            // Act
            var page2 = PaginatedList<Student>.Create(query, 2, 2);

            // Assert
            Assert.Equal(2, page2.PageIndex);
            Assert.Equal(allSorted[2].ID, page2[0].ID);
            Assert.Equal(allSorted[3].ID, page2[1].ID);
        }

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            // Arrange
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act
            var result = PaginatedList<Student>.Create(query, 1, 2);

            // Assert
            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            // Arrange
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act
            var result = PaginatedList<Student>.Create(query, 2, 2);

            // Assert
            Assert.True(result.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_FirstPageWithMorePages_ReturnsTrue()
        {
            // Arrange
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act
            var result = PaginatedList<Student>.Create(query, 1, 2);

            // Assert - 5 items / 2 per page = 3 pages, so page 1 has next
            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            // Arrange
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act - page 3 is the last page (5 items / 2 per page = 3 pages)
            var result = PaginatedList<Student>.Create(query, 3, 2);

            // Assert
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_SinglePage_NoNavigationNeeded()
        {
            // Arrange - 5 items, page size 10 = only 1 page
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act
            var result = PaginatedList<Student>.Create(query, 1, 10);

            // Assert
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
            Assert.Equal(5, result.Count);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            // Arrange
            var context = TestDbContextFactory.Create();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act
            var result = PaginatedList<Student>.Create(query, 1, 10);

            // Assert
            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
            Assert.Equal(1, result.PageIndex);
        }

        [Fact]
        public void Constructor_SetsPropertiesCorrectly()
        {
            // Arrange
            var items = new List<string> { "a", "b", "c" };

            // Act
            var list = new PaginatedList<string>(items, 10, 2, 3);

            // Assert
            Assert.Equal(2, list.PageIndex);
            Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
            Assert.Equal(3, list.Count);
            Assert.Equal("a", list[0]);
            Assert.Equal("b", list[1]);
            Assert.Equal("c", list[2]);
        }

        [Fact]
        public void HasPreviousPage_PageOne_ReturnsFalse()
        {
            // Arrange
            var list = new PaginatedList<string>(new List<string> { "a" }, 5, 1, 2);

            // Assert
            Assert.False(list.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_WhenPageIndexEqualsTotal_ReturnsFalse()
        {
            // Arrange - page 3 of 3
            var list = new PaginatedList<string>(new List<string> { "a" }, 5, 3, 2);

            // Assert
            Assert.False(list.HasNextPage);
        }

        [Fact]
        public void HasNextPage_WhenPageIndexLessThanTotal_ReturnsTrue()
        {
            // Arrange - page 1 of 3
            var list = new PaginatedList<string>(new List<string> { "a", "b" }, 5, 1, 2);

            // Assert
            Assert.True(list.HasNextPage);
        }
    }
}

using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextFactory
    {
        public static SchoolContext Create(string dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;

            var context = new SchoolContext(options);
            context.Database.EnsureCreated();
            return context;
        }

        public static SchoolContext CreateWithStudents(string dbName = null)
        {
            var context = Create(dbName);
            SeedStudents(context);
            return context;
        }

        public static SchoolContext CreateWithCourses(string dbName = null)
        {
            var context = Create(dbName);
            SeedDepartments(context);
            SeedCourses(context);
            return context;
        }

        public static SchoolContext CreateWithInstructors(string dbName = null)
        {
            var context = Create(dbName);
            SeedDepartments(context);
            SeedCourses(context);
            SeedInstructors(context);
            return context;
        }

        public static SchoolContext CreateFullySeeded(string dbName = null)
        {
            var context = Create(dbName);
            SeedDepartments(context);
            SeedCourses(context);
            SeedInstructors(context);
            SeedStudents(context);
            SeedEnrollments(context);
            return context;
        }

        private static void SeedStudents(SchoolContext context)
        {
            if (context.Students.Any()) return;

            context.Students.AddRange(
                new Student { ID = 1, LastName = "Alexander", FirstMidName = "Carson", EnrollmentDate = new DateTime(2020, 9, 1) },
                new Student { ID = 2, LastName = "Alonso", FirstMidName = "Meredith", EnrollmentDate = new DateTime(2019, 9, 1) },
                new Student { ID = 3, LastName = "Anand", FirstMidName = "Arturo", EnrollmentDate = new DateTime(2021, 9, 1) },
                new Student { ID = 4, LastName = "Barzdukas", FirstMidName = "Gytis", EnrollmentDate = new DateTime(2020, 9, 1) },
                new Student { ID = 5, LastName = "Li", FirstMidName = "Yan", EnrollmentDate = new DateTime(2019, 9, 1) }
            );
            context.SaveChanges();
        }

        private static void SeedDepartments(SchoolContext context)
        {
            if (context.Departments.Any()) return;

            context.Departments.AddRange(
                new Department { DepartmentID = 1, Name = "English", Budget = 350000, StartDate = new DateTime(2007, 9, 1) },
                new Department { DepartmentID = 2, Name = "Mathematics", Budget = 100000, StartDate = new DateTime(2007, 9, 1) },
                new Department { DepartmentID = 3, Name = "Engineering", Budget = 350000, StartDate = new DateTime(2007, 9, 1) }
            );
            context.SaveChanges();
        }

        private static void SeedCourses(SchoolContext context)
        {
            if (context.Courses.Any()) return;

            context.Courses.AddRange(
                new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 3 },
                new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = 1 },
                new Course { CourseID = 4041, Title = "Macroeconomics", Credits = 3, DepartmentID = 1 },
                new Course { CourseID = 2021, Title = "Composition", Credits = 3, DepartmentID = 1 },
                new Course { CourseID = 1045, Title = "Calculus", Credits = 4, DepartmentID = 2 }
            );
            context.SaveChanges();
        }

        private static void SeedInstructors(SchoolContext context)
        {
            if (context.Instructors.Any()) return;

            context.Instructors.AddRange(
                new Instructor { ID = 10, LastName = "Zheng", FirstMidName = "Roger", HireDate = new DateTime(2004, 2, 12), CourseAssignments = new System.Collections.Generic.List<CourseAssignment>() },
                new Instructor { ID = 11, LastName = "Kapoor", FirstMidName = "Candace", HireDate = new DateTime(2001, 1, 15), CourseAssignments = new System.Collections.Generic.List<CourseAssignment>() },
                new Instructor { ID = 12, LastName = "Fakhouri", FirstMidName = "Fadi", HireDate = new DateTime(2002, 7, 6), CourseAssignments = new System.Collections.Generic.List<CourseAssignment>() }
            );
            context.SaveChanges();

            // Add office assignments
            context.OfficeAssignments.Add(new OfficeAssignment { InstructorID = 10, Location = "Smith 17" });
            context.SaveChanges();

            // Add course assignments
            context.CourseAssignments.AddRange(
                new CourseAssignment { InstructorID = 10, CourseID = 1050 },
                new CourseAssignment { InstructorID = 11, CourseID = 4022 },
                new CourseAssignment { InstructorID = 12, CourseID = 2021 }
            );
            context.SaveChanges();
        }

        private static void SeedEnrollments(SchoolContext context)
        {
            if (context.Enrollments.Any()) return;

            context.Enrollments.AddRange(
                new Enrollment { CourseID = 1050, StudentID = 1, Grade = Grade.A },
                new Enrollment { CourseID = 4022, StudentID = 1, Grade = Grade.C },
                new Enrollment { CourseID = 1050, StudentID = 2, Grade = Grade.B },
                new Enrollment { CourseID = 4041, StudentID = 3, Grade = null }
            );
            context.SaveChanges();
        }
    }
}

using System;
using Xunit;
using ContosoUniversity.Services;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            // Drain the static queue to isolate tests
            while (_service.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain the static queue after each test
            while (_service.ReceiveNotification() != null) { }
            _service.Dispose();
        }

        [Fact]
        public void SendNotification_WithDisplayName_EnqueuesCorrectly()
        {
            // Act
            _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
            Assert.Contains("John Doe", notification.Message);
            Assert.Contains("created", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesIdFormat()
        {
            // Act
            _service.SendNotification("Course", "42", EntityOperation.UPDATE, "teacher");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("UPDATE", notification.Operation);
            Assert.Equal("teacher", notification.CreatedBy);
            Assert.Contains("(ID: 42)", notification.Message);
            Assert.Contains("updated", notification.Message);
        }

        [Fact]
        public void SendNotification_NullUserName_DefaultsToSystem()
        {
            // Act
            _service.SendNotification("Student", "5", EntityOperation.DELETE);

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void ReceiveNotification_DequeuesInOrder()
        {
            // Arrange
            _service.SendNotification("Student", "1", "First", EntityOperation.CREATE);
            _service.SendNotification("Course", "2", "Second", EntityOperation.UPDATE);
            _service.SendNotification("Department", "3", "Third", EntityOperation.DELETE);

            // Act & Assert
            var first = _service.ReceiveNotification();
            Assert.Equal("Student", first.EntityType);
            Assert.Equal("1", first.EntityId);

            var second = _service.ReceiveNotification();
            Assert.Equal("Course", second.EntityType);
            Assert.Equal("2", second.EntityId);

            var third = _service.ReceiveNotification();
            Assert.Equal("Department", third.EntityType);
            Assert.Equal("3", third.EntityId);
        }

        [Fact]
        public void ReceiveNotification_ReturnsNull_WhenEmpty()
        {
            // Act
            var result = _service.ReceiveNotification();

            // Assert
            Assert.Null(result);
        }

        [Fact]
        public void SendNotification_EnforcesMaxQueueLength()
        {
            // Arrange - fill beyond max (500)
            for (int i = 0; i < 510; i++)
            {
                _service.SendNotification("Entity", i.ToString(), $"Item{i}", EntityOperation.CREATE);
            }

            // Act - count remaining items
            int count = 0;
            while (_service.ReceiveNotification() != null)
            {
                count++;
            }

            // Assert - queue should not exceed 500
            Assert.True(count <= 500, $"Queue had {count} items, expected <= 500");
        }

        [Fact]
        public void GenerateMessage_Create_ProducesCorrectString()
        {
            // Act
            _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE);

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.Equal("New Student 'John Doe' has been created", notification.Message);
        }

        [Fact]
        public void GenerateMessage_Update_ProducesCorrectString()
        {
            // Act
            _service.SendNotification("Course", "101", "Chemistry", EntityOperation.UPDATE);

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.Equal("Course 'Chemistry' has been updated", notification.Message);
        }

        [Fact]
        public void GenerateMessage_Delete_ProducesCorrectString()
        {
            // Act
            _service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE);

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.Equal("Department 'Engineering' has been deleted", notification.Message);
        }

        [Fact]
        public void GenerateMessage_WithoutDisplayName_Create_UsesIdFormat()
        {
            // Act
            _service.SendNotification("Student", "99", EntityOperation.CREATE);

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.Equal("New Student (ID: 99) has been created", notification.Message);
        }

        [Fact]
        public void GenerateMessage_WithoutDisplayName_Update_UsesIdFormat()
        {
            // Act
            _service.SendNotification("Course", "42", EntityOperation.UPDATE);

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.Equal("Course (ID: 42) has been updated", notification.Message);
        }

        [Fact]
        public void GenerateMessage_WithoutDisplayName_Delete_UsesIdFormat()
        {
            // Act
            _service.SendNotification("Department", "7", EntityOperation.DELETE);

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.Equal("Department (ID: 7) has been deleted", notification.Message);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            // Act & Assert
            var exception = Record.Exception(() => _service.Dispose());
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_SetsCreatedAt()
        {
            // Arrange
            var before = DateTime.Now;

            // Act
            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

            // Assert
            var after = DateTime.Now;
            var notification = _service.ReceiveNotification();
            Assert.InRange(notification.CreatedAt, before, after);
        }

        [Fact]
        public void SendNotification_SetsIsReadToFalse()
        {
            // Act
            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.False(notification.IsRead);
            Assert.Null(notification.ReadAt);
        }
    }
}

