using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;
using Microsoft.AspNetCore.Mvc;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;
        private readonly NotificationService _notificationService;

        public NotificationsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new NotificationsController(_context);
            _notificationService = new NotificationService();
            // Drain the static queue to isolate tests
            while (_notificationService.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain queue
            while (_notificationService.ReceiveNotification() != null) { }
            _controller.Dispose();
            _context.Dispose();
            _notificationService.Dispose();
        }

        [Fact]
        public void GetNotifications_ReturnsNotifications_WhenAvailable()
        {
            // Arrange - enqueue some notifications
            _notificationService.SendNotification("Student", "1", "John", EntityOperation.CREATE);
            _notificationService.SendNotification("Course", "2", "Math", EntityOperation.UPDATE);

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.NotNull(result);
            var json = result.Value;
            Assert.NotNull(json);
            var successProp = json.GetType().GetProperty("success");
            Assert.NotNull(successProp);
            Assert.True((bool)successProp.GetValue(json));

            var countProp = json.GetType().GetProperty("count");
            Assert.NotNull(countProp);
            var count = (int)countProp.GetValue(json);
            Assert.True(count >= 1);
        }

        [Fact]
        public void GetNotifications_ReturnsEmptyList_WhenNoNotifications()
        {
            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.NotNull(result);
            var json = result.Value;
            var successProp = json.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(json));

            var countProp = json.GetType().GetProperty("count");
            var count = (int)countProp.GetValue(json);
            Assert.Equal(0, count);
        }

        [Fact]
        public void GetNotifications_LimitsToTen()
        {
            // Arrange - add 15 notifications
            for (int i = 0; i < 15; i++)
            {
                _notificationService.SendNotification("Entity", i.ToString(), $"Item{i}", EntityOperation.CREATE);
            }

            // Act
            var result = _controller.GetNotifications();

            // Assert
            var json = result.Value;
            var countProp = json.GetType().GetProperty("count");
            var count = (int)countProp.GetValue(json);
            Assert.True(count <= 10, $"Expected at most 10, got {count}");
        }

        [Fact]
        public void GetNotifications_ReturnsSuccessTrue()
        {
            // Act
            var result = _controller.GetNotifications();

            // Assert
            var json = result.Value;
            var successProp = json.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(json));
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccessJson()
        {
            // Act
            var result = _controller.MarkAsRead(1);

            // Assert
            Assert.NotNull(result);
            var json = result.Value;
            var successProp = json.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(json));
        }

        [Fact]
        public void MarkAsRead_WithAnyId_ReturnsSuccess()
        {
            // Act - test with various IDs (it's a no-op)
            var result1 = _controller.MarkAsRead(0);
            var result2 = _controller.MarkAsRead(999);

            // Assert
            var json1 = result1.Value;
            var json2 = result2.Value;
            Assert.True((bool)json1.GetType().GetProperty("success").GetValue(json1));
            Assert.True((bool)json2.GetType().GetProperty("success").GetValue(json2));
        }

        [Fact]
        public void Index_ReturnsView()
        {
            // Act
            var result = _controller.Index();

            // Assert
            Assert.IsType<ViewResult>(result);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;
using Microsoft.EntityFrameworkCore;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests.Utilities
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_SetsCorrectPageIndex()
        {
            // Arrange
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act
            var result = PaginatedList<Student>.Create(query, 1, 2);

            // Assert
            Assert.Equal(1, result.PageIndex);
        }

        [Fact]
        public void Create_CalculatesTotalPagesCorrectly()
        {
            // Arrange - 5 students, page size 2 => ceil(5/2) = 3 pages
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act
            var result = PaginatedList<Student>.Create(query, 1, 2);

            // Assert
            Assert.Equal(3, result.TotalPages);
        }

        [Fact]
        public void Create_ReturnsCorrectPageSize()
        {
            // Arrange
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act
            var result = PaginatedList<Student>.Create(query, 1, 2);

            // Assert
            Assert.Equal(2, result.Count);
        }

        [Fact]
        public void Create_PageTwo_SkipsFirstPageItems()
        {
            // Arrange
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);
            var allSorted = query.ToList();

            // Act
            var page2 = PaginatedList<Student>.Create(query, 2, 2);

            // Assert
            Assert.Equal(2, page2.PageIndex);
            Assert.Equal(allSorted[2].ID, page2[0].ID);
            Assert.Equal(allSorted[3].ID, page2[1].ID);
        }

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            // Arrange
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act
            var result = PaginatedList<Student>.Create(query, 1, 2);

            // Assert
            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            // Arrange
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act
            var result = PaginatedList<Student>.Create(query, 2, 2);

            // Assert
            Assert.True(result.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_FirstPageWithMorePages_ReturnsTrue()
        {
            // Arrange
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act
            var result = PaginatedList<Student>.Create(query, 1, 2);

            // Assert - 5 items / 2 per page = 3 pages, so page 1 has next
            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            // Arrange
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act - page 3 is the last page (5 items / 2 per page = 3 pages)
            var result = PaginatedList<Student>.Create(query, 3, 2);

            // Assert
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_SinglePage_NoNavigationNeeded()
        {
            // Arrange - 5 items, page size 10 = only 1 page
            var context = TestDbContextFactory.CreateWithStudents();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act
            var result = PaginatedList<Student>.Create(query, 1, 10);

            // Assert
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
            Assert.Equal(5, result.Count);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            // Arrange
            var context = TestDbContextFactory.Create();
            var query = context.Students.OrderBy(s => s.LastName);

            // Act
            var result = PaginatedList<Student>.Create(query, 1, 10);

            // Assert
            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
            Assert.Equal(1, result.PageIndex);
        }

        [Fact]
        public void Constructor_SetsPropertiesCorrectly()
        {
            // Arrange
            var items = new List<string> { "a", "b", "c" };

            // Act
            var list = new PaginatedList<string>(items, 10, 2, 3);

            // Assert
            Assert.Equal(2, list.PageIndex);
            Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
            Assert.Equal(3, list.Count);
            Assert.Equal("a", list[0]);
            Assert.Equal("b", list[1]);
            Assert.Equal("c", list[2]);
        }

        [Fact]
        public void HasPreviousPage_PageOne_ReturnsFalse()
        {
            // Arrange
            var list = new PaginatedList<string>(new List<string> { "a" }, 5, 1, 2);

            // Assert
            Assert.False(list.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_WhenPageIndexEqualsTotal_ReturnsFalse()
        {
            // Arrange - page 3 of 3
            var list = new PaginatedList<string>(new List<string> { "a" }, 5, 3, 2);

            // Assert
            Assert.False(list.HasNextPage);
        }

        [Fact]
        public void HasNextPage_WhenPageIndexLessThanTotal_ReturnsTrue()
        {
            // Arrange - page 1 of 3
            var list = new PaginatedList<string>(new List<string> { "a", "b" }, 5, 1, 2);

            // Assert
            Assert.True(list.HasNextPage);
        }
    }
}

