+using System;
+using Xunit;
+using ContosoUniversity.Services;
+using ContosoUniversity.Models;
+
+namespace ContosoUniversity.Tests.Services
+{
+    public class NotificationServiceTests : IDisposable
+    {
+        private readonly NotificationService _service;
+
+        public NotificationServiceTests()
+        {
+            _service = new NotificationService();
+            // Drain the static queue to isolate tests
+            while (_service.ReceiveNotification() != null) { }
+        }
+
+        public void Dispose()
+        {
+            // Drain the static queue after each test
+            while (_service.ReceiveNotification() != null) { }
+            _service.Dispose();
+        }
+
+        [Fact]
+        public void SendNotification_WithDisplayName_EnqueuesCorrectly()
+        {
+            // Act
+            _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "admin");
+
+            // Assert
+            var notification = _service.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Student", notification.EntityType);
+            Assert.Equal("1", notification.EntityId);
+            Assert.Equal("CREATE", notification.Operation);
+            Assert.Equal("admin", notification.CreatedBy);
+            Assert.False(notification.IsRead);
+            Assert.Contains("John Doe", notification.Message);
+            Assert.Contains("created", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_WithoutDisplayName_UsesIdFormat()
+        {
+            // Act
+            _service.SendNotification("Course", "42", EntityOperation.UPDATE, "teacher");
+
+            // Assert
+            var notification = _service.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Course", notification.EntityType);
+            Assert.Equal("42", notification.EntityId);
+            Assert.Equal("UPDATE", notification.Operation);
+            Assert.Equal("teacher", notification.CreatedBy);
+            Assert.Contains("(ID: 42)", notification.Message);
+            Assert.Contains("updated", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_NullUserName_DefaultsToSystem()
+        {
+            // Act
+            _service.SendNotification("Student", "5", EntityOperation.DELETE);
+
+            // Assert
+            var notification = _service.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("System", notification.CreatedBy);
+        }
+
+        [Fact]
+        public void ReceiveNotification_DequeuesInOrder()
+        {
+            // Arrange
+            _service.SendNotification("Student", "1", "First", EntityOperation.CREATE);
+            _service.SendNotification("Course", "2", "Second", EntityOperation.UPDATE);
+            _service.SendNotification("Department", "3", "Third", EntityOperation.DELETE);
+
+            // Act & Assert
+            var first = _service.ReceiveNotification();
+            Assert.Equal("Student", first.EntityType);
+            Assert.Equal("1", first.EntityId);
+
+            var second = _service.ReceiveNotification();
+            Assert.Equal("Course", second.EntityType);
+            Assert.Equal("2", second.EntityId);
+
+            var third = _service.ReceiveNotification();
+            Assert.Equal("Department", third.EntityType);
+            Assert.Equal("3", third.EntityId);
+        }
+
+        [Fact]
+        public void ReceiveNotification_ReturnsNull_WhenEmpty()
+        {
+            // Act
+            var result = _service.ReceiveNotification();
+
+            // Assert
+            Assert.Null(result);
+        }
+
+        [Fact]
+        public void SendNotification_EnforcesMaxQueueLength()
+        {
+            // Arrange - fill beyond max (500)
+            for (int i = 0; i < 510; i++)
+            {
+                _service.SendNotification("Entity", i.ToString(), $"Item{i}", EntityOperation.CREATE);
+            }
+
+            // Act - count remaining items
+            int count = 0;
+            while (_service.ReceiveNotification() != null)
+            {
+                count++;
+            }
+
+            // Assert - queue should not exceed 500
+            Assert.True(count <= 500, $"Queue had {count} items, expected <= 500");
+        }
+
+        [Fact]
+        public void GenerateMessage_Create_ProducesCorrectString()
+        {
+            // Act
+            _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE);
+
+            // Assert
+            var notification = _service.ReceiveNotification();
+            Assert.Equal("New Student 'John Doe' has been created", notification.Message);
+        }
+
+        [Fact]
+        public void GenerateMessage_Update_ProducesCorrectString()
+        {
+            // Act
+            _service.SendNotification("Course", "101", "Chemistry", EntityOperation.UPDATE);
+
+            // Assert
+            var notification = _service.ReceiveNotification();
+            Assert.Equal("Course 'Chemistry' has been updated", notification.Message);
+        }
+
+        [Fact]
+        public void GenerateMessage_Delete_ProducesCorrectString()
+        {
+            // Act
+            _service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE);
+
+            // Assert
+            var notification = _service.ReceiveNotification();
+            Assert.Equal("Department 'Engineering' has been deleted", notification.Message);
+        }
+
+        [Fact]
+        public void GenerateMessage_WithoutDisplayName_Create_UsesIdFormat()
+        {
+            // Act
+            _service.SendNotification("Student", "99", EntityOperation.CREATE);
+
+            // Assert
+            var notification = _service.ReceiveNotification();
+            Assert.Equal("New Student (ID: 99) has been created", notification.Message);
+        }
+
+        [Fact]
+        public void GenerateMessage_WithoutDisplayName_Update_UsesIdFormat()
+        {
+            // Act
+            _service.SendNotification("Course", "42", EntityOperation.UPDATE);
+
+            // Assert
+            var notification = _service.ReceiveNotification();
+            Assert.Equal("Course (ID: 42) has been updated", notification.Message);
+        }
+
+        [Fact]
+        public void GenerateMessage_WithoutDisplayName_Delete_UsesIdFormat()
+        {
+            // Act
+            _service.SendNotification("Department", "7", EntityOperation.DELETE);
+
+            // Assert
+            var notification = _service.ReceiveNotification();
+            Assert.Equal("Department (ID: 7) has been deleted", notification.Message);
+        }
+
+        [Fact]
+        public void Dispose_DoesNotThrow()
+        {
+            // Act & Assert
+            var exception = Record.Exception(() => _service.Dispose());
+            Assert.Null(exception);
+        }
+
+        [Fact]
+        public void SendNotification_SetsCreatedAt()
+        {
+            // Arrange
+            var before = DateTime.Now;
+
+            // Act
+            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE);
+
+            // Assert
+            var after = DateTime.Now;
+            var notification = _service.ReceiveNotification();
+            Assert.InRange(notification.CreatedAt, before, after);
+        }
+
+        [Fact]
+        public void SendNotification_SetsIsReadToFalse()
+        {
+            // Act
+            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE);
+
+            // Assert
+            var notification = _service.ReceiveNotification();
+            Assert.False(notification.IsRead);
+            Assert.Null(notification.ReadAt);
+        }
+    }
+}
+

